import { useEffect, useState } from "react";
import { getGameDetails, getScores } from "../service";
import { Alert, Col, Container, Row } from "react-bootstrap";
import { auth } from "../firebase";

const Results = () => {
    const [userData, setUserData] = useState({});
    const [allscores, setAllScores] = useState([]);
    const [canrun, setCanrun] = useState({});

    const initialize = async () => {
        const d = await getGameDetails();
        setCanrun(d.voteCompleted);
        if (d.voteCompleted) {
            const u = await getScores();
            setAllScores(u);
            setUserData(auth.currentUser);
        }
    }
    useEffect(() => {
        initialize();
	}, []);

    return(
        <>
        {
            canrun
            ? 
            <Container>
                <Row>
                    <Col className="text-center">
                        <h3>Κατάταξη</h3>
                    </Col>
                </Row>
                <Row>
                    <Col xs={1}>#</Col>
                    <Col>Όνομα</Col>
                    <Col>Βαθμολογία</Col>
                </Row>
                {
                    allscores.length > 0 
                    ? allscores.map((s, i) => <ScoreEntry key={i} aa={i+1} name={s.name} score={s.score} isMe={s.name === userData.username}/>)
                    : null
                } 
            </Container>
            : <Alert variant="warning">
                Η ψηφοοφρία βρίσκεται σε εξέληξη
            </Alert>
        }
        </>
    );
}

const ScoreEntry = ({aa, name, score, isMe}) => {
    const [color, setColor] = useState('#000000')
    const [border, setBorder] = useState('');

    useEffect(()=>{
        let c, b = '';
        
        switch (aa) {
            case 1:
                c = 'gold';
                break;
            case 2:
                c = 'silver';
                break;
            case 3:
                c = '#CE8946';
                break;
            default:
                c = 'black'
                break;
        }
        if(isMe)
            b = '2px solid ' + c;
        setColor(c); 
        setBorder(b);

    }, [])
    return(
        <Row style={{ color: color, border: border}}>
            <Col xs={1}>{aa}</Col>
            <Col>{name}</Col>
            <Col>{score}</Col>
        </Row>
    )

}

export default Results;