// src/components/Login.js
import React, { useState } from "react";
import { signInWithEmailAndPassword } from "firebase/auth";
import { auth } from "../firebase";
import { Button, FloatingLabel, Form, InputGroup } from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import { Eye, EyeSlash } from "react-bootstrap-icons";

const Login = ({language}) => {
	const [email, setEmail] = useState("");
	const [password, setPassword] = useState("");
	const [error, setError] = useState("");
	const [isVissible, setIsVissible] = useState(false);
	const navigate = useNavigate();

	const handleLogin = async (e) => {
		e.preventDefault();
		try {
			await signInWithEmailAndPassword(auth, email, password);
			navigate('/prize');
		} catch (err) {
			setError(err.message);
		}
	};

	return (
		<Form onSubmit={handleLogin}  style={{ width: '80vw', maxWidth: '350px' }}>
			<Form.Group className="mb-3" controlId="formBasicEmail" onChange={(e) => setEmail(e.target.value)}>
				<FloatingLabel label={language.email} className="mb-3">
					<Form.Control type="email" placeholder={language.email} />
				</FloatingLabel>
			</Form.Group>

			<Form.Group>
				<InputGroup controlId="formBasicPassword" onChange={(e) => setPassword(e.target.value)}>
					<FloatingLabel label={language.password}>
						<Form.Control type={isVissible? "text" : "password"} placeholder={language.password} />
					</FloatingLabel>
					<InputGroup.Text id="basic-addon1" onClick={()=>setIsVissible(!isVissible)}>
						{isVissible ? <Eye/> : <EyeSlash/>	}				
					</InputGroup.Text>
				</InputGroup>

				<Form.Text className="text-muted mb-3">
					Τουλάχιστον 6 χαρακτήρες
				</Form.Text>
			</Form.Group>

			<Button variant="primary" type="submit">
				{language.login}
			</Button>
			{error && <p style={{ color: "red" }}>{error}</p>}
		</Form>
	);
};

export default Login;