export async function getAllCountries() {
    const q = query(
        collection(db, "countries")
    );
    const countriesSnapshot = await getDocs(q);
    return countriesSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
}

export async function updateCountries(newList) {
    const ref = doc(db, 'details', 'config')
    await updateDoc(ref, {
        countries: newList
    });
}

export async function getUserbyEmail(email) {
    const q = query(
        collection(db, "users"),
        where("email", "==", email)
    );
    const docSnap = await getDocs(q);
    if(docSnap.empty)
        return null;
    const userData = docSnap.docs[0].data();

    return {...userData, id: docSnap.docs[0].id }
}

export async function getUser(name) {
    const q = query(
        collection(db, "users"),
        where("username", "==", name)
    );
    const docSnap = await getDocs(q);
    if(docSnap.empty)
        return null;
    const userData = docSnap.docs[0].data();

    return {...userData, id: docSnap.docs[0].id }
}


export async function createUser(mail, name) {
    const c = await getCountries(false);
    const cc  = c.map(doc => ({ ...doc, pickedBy: null }));
    const prizes = [9,11,13]
    const data = {
        email: mail,
        username: name,
        bonus: prizes[Math.floor(Math.random() * 3)],
        countries: cc,
        score: 0
    };
    const col = collection(db, "users");
    const docRef = doc(col);
    await setDoc(docRef, data);
    return data;
}

export async function getScores() {
    const q = query(
        collection(db, "users")
    );
    const docSnap = await getDocs(q);

    return docSnap.docs.map(doc => ({ name: doc.data().username, score: doc.data().score })).sort((a,b) => b.score - a.score);
    
}

export async function createScores() {

    // const docSnapC = await getDocs(
    //     collection(db, "countries"),
    //     where("isLive", "==", true)
    // );
    // docSnapC.docs.forEach(doc => {
    //     countries[doc.data().name] = doc.data().score;
    // });

    const countries = {};
    const c = await getCountries();
    c.forEach(doc => {
        countries[doc.name] = doc.score;
    })

    const userScores = [];
    const q = query(
        collection(db, "users")
    );
    const docSnap = await getDocs(q);

    for (const d of docSnap.docs) {
        const id = d.id;
        let score = 0;

        d.data().countries.forEach(c => {
            if (c.pickedBy) {
                score += c.pickedBy * countries[c.name];
            }
        });

        const userDocRef = doc(db, "users", id);

        await updateDoc(userDocRef, {
            score: score
        });

        userScores.push({
            username: d.data().username,
            score: score
        });
    }
    
    return userScores;
}

export async function getGameDetails() {
    const ref = doc(db, 'details', 'config')
    const d = await getDoc(ref);
    return d.data();
}