import { useEffect, useState } from "react";
import { Button, Col, Container, FloatingLabel, Form, InputGroup, Row, Stack } from "react-bootstrap";
import { createScores, getCountries, updateCountries } from "../service";
import { Eye, EyeSlash } from "react-bootstrap-icons";

const CountriesManage = () => {
    const [countries, setCountries] = useState([]);
    const [users, setUsers] = useState([]);
    const [unlocked, setUnlocked] = useState(false);
    const [isVissible, setIsVissible] = useState(false);
    
    
    const fetchCountries = async () => {
        const countriesList = await getCountries();
        setCountries(countriesList);
    };

    const update = async (i, obj) => {
        const newList = [...countries];
        newList[i] = obj;
        setCountries(newList);
        await updateCountries(newList);
    }

    useEffect(() => {
        fetchCountries();
    }, []);


    const calculateFun = async () => {
        const u = await createScores();
        setUsers(u);
    }

    const handleSignup = (e) => {
        setUnlocked(e.target.value == "adminpass")
    }

    return (
        <Container>{ unlocked
        ? 
            <Row>
                <Col>
                    <Stack gap={3} className="align-items-center"> 
                    {
                        countries.length > 0
                        ?
                        countries.map((country, i) => (
                            <CountryEntry key={i} c={country} index={i} update={update}/>
                        ))
                        : <p>Loading countries...</p>
                    }
                    </Stack>
                </Col>
                <Col>
                    <Row>
                        <Col>
                            <Button onClick={calculateFun}>
                                Calculate
                            </Button>
                        </Col>
                    </Row>
                    {
                        users.length > 0
                        ? users.map(u=><Row><Col>{u.username}</Col><Col>{u.score}</Col></Row>)
                        : <p>Loading users...</p>
                    }
                </Col>
            </Row>
        : <Form style={{ width: '80vw', maxWidth: '350px' }}>
                
                    <Form.Group onChange={handleSignup}>
                        <InputGroup controlId="formBasicPassword">
                            <FloatingLabel label='pass'>
                                <Form.Control type={isVissible? "text" : "password"} placeholder="password" />
                            </FloatingLabel>
                            <InputGroup.Text id="basic-addon1" onClick={()=>setIsVissible(!isVissible)}>
                                {isVissible ? <Eye/> : <EyeSlash/>	}				
                            </InputGroup.Text>
                        </InputGroup>

                    </Form.Group>
                </Form>
        }
        </Container>
    );
}


const CountryEntry = ({c, index, update}) => {
    const [country, setCountry] = useState({});

    useEffect(()=>{
        setCountry({...c})
    }, [])

    const updateCountryStatus = async (e) => {
        const n = {...country};
        n.isLive = e.target.checked;
        setCountry(n);
        update(index, n);
    };

    const updateCountryScore = async (e) => {
        const newScore = parseInt(e.target.value);
        if (isNaN(newScore)) return;
        const n = {...country};
        n.score = newScore;
        setCountry(n);
        update(index, n);
    }
    const onChnageScore = async (e) => {
        const newScore = parseInt(e.target.value);
        if (isNaN(newScore)) return;
        const n = {...country};
        n.score = newScore;
        setCountry(n);
    }

    const updateCountryAA = async (e) => {
    }

    return (
        <Row key={country.id} className="align-items-center justify-content-center">
            <Col xs='auto' >{country.name}</Col>
            <Col xs='auto' >
                <Form.Check type="switch" id={`${country.id}`} checked={country.isLive} onChange={updateCountryStatus}/>
            </Col>
            <Col xs='auto' style={{width: '150px'}}>
                <Form.Group onBlur={updateCountryScore}>
                    <FloatingLabel controlId="floatingInput" label="Score" className="mb-3">
                        <Form.Control type="number" value={country.score} onChange={onChnageScore}/>
                    </FloatingLabel>
                </Form.Group>
            </Col>

            {/* <Col xs='auto' style={{width: '100px'}}>
                <Form.Group onBlur={updateCountryAA} >
                    <FloatingLabel controlId="floatingInput" label="#" className="mb-3">
                        <Form.Control type="number" value={country.aa} onChange={()=>{}} disabled/>
                    </FloatingLabel>
                </Form.Group>
            </Col> */}
        </Row>
    );
}


export default CountriesManage;