// src/components/Signup.js
import React, { useState } from "react";
import { createUserWithEmailAndPassword, updateProfile } from "firebase/auth";
import { auth } from "../firebase";
import { Button, FloatingLabel, Form, InputGroup } from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import { Eye, EyeSlash } from "react-bootstrap-icons";

const Signup = ({language}) => {
	const [email, setEmail] = useState("");
	const [password, setPassword] = useState("");
	const [name, setName] = useState("");
	const [error, setError] = useState("");
	const [isVissible, setIsVissible] = useState(false);
	const navigate = useNavigate();

	const handleSignup = async (e) => {
		e.preventDefault();
		try {
			if(name == '')
			{
				setError('Το όνομα είναι κενό');
				return
			}
			const userCredential = await createUserWithEmailAndPassword(auth, email, password);
			const user = userCredential.user;

			// Add username
			await updateProfile(user, {
				displayName: name,
			});
			navigate("/prize");
		} catch (err) {
			setError(err.message);
		}
	};

	return (
		<Form onSubmit={handleSignup} style={{ width: '80vw', maxWidth: '350px' }}>

			<Form.Group className="mb-3" controlId="formBasicPassword" onChange={(e) => setName(e.target.value)}>
				<FloatingLabel label="Όνομα" className="mb-3">
					<Form.Control type="text" placeholder="Όνομα" />
				</FloatingLabel>
			</Form.Group>
			
			<Form.Group>
				<InputGroup controlId="formBasicPassword" onChange={(e) => setPassword(e.target.value)}>
					<FloatingLabel label={language.password}>
						<Form.Control type={isVissible? "text" : "password"} placeholder={language.password} />
					</FloatingLabel>
					<InputGroup.Text id="basic-addon1" onClick={()=>setIsVissible(!isVissible)}>
						{isVissible ? <Eye/> : <EyeSlash/>	}				
					</InputGroup.Text>
				</InputGroup>

				<Form.Text className="text-muted mb-3">
					Τουλάχιστον 6 χαρακτήρες
				</Form.Text>
			</Form.Group>

			<Form.Group className="mb-3 justify-content-md-center" 
			controlId="formBasicEmail" 
			onChange={(e) => setEmail(e.target.value)}>
				<FloatingLabel label={language.email}>
					<Form.Control type="email" placeholder={language.email} />
				</FloatingLabel>
				<Form.Text className="text-muted mb-3">
					{language.diclaim}
				</Form.Text>
			</Form.Group>

			
			<Button variant="success" type="submit" className="align-self-right">
				{language.signup}
			</Button>
			{error && <p style={{ color: "red" }}>{error}</p>}
		</Form>
	);
};

export default Signup;