import { useEffect, useRef, useState } from "react";
import { Wheel } from "react-custom-roulette";
import { auth } from "../firebase";
import { createUser, getUserbyEmail } from "../service";
import { useNavigate } from "react-router-dom";
import { Alert, Button, Col, Container, Row } from "react-bootstrap";
const language = {
	prizes: ['8', '9','10', '11','12', '13']
}


const messages = [
	'Η βαθμολογία 8 προστέθηκε στις επιλογές σου!!!',
	'Η βαθμολογία 9 προστέθηκε στις επιλογές σου!!!',
	'Η βαθμολογία 11 προστέθηκε στις επιλογές σου!!!',
	'Η βαθμολογία 11 προστέθηκε στις επιλογές σου!!!',
	'Η βαθμολογία 12 προστέθηκε στις επιλογές σου!!!',
	'Η βαθμολογία 13 προστέθηκε στις επιλογές σου!!!',
]
const MyWheel = () => {
	const[start, setStart] = useState(false)
	const[prize, setPrize] = useState(-1);
	const[show, setShow] = useState(false);
	const nav = useNavigate();
	const spin = useRef(new Audio("/spin.mp3"));
	const win = useRef(new Audio("/win.mp3"));

	const getDetails = async () => {
		const currentUser = auth.currentUser;
		let userData = await getUserbyEmail(currentUser.email);
		if (userData) {
			nav('/');
			return;
		}
		userData = await createUser(currentUser.email, currentUser.displayName);
		setPrize(userData.bonus-8)
	}

	const startSpin = () => {
		spin.current.play();		
		setStart(true)
	}
	const stopSpin = () => {
		spin.current.pause();
  		spin.current.currentTime = 0;
  		win.current.play();	
		setShow(true)
	}

	const finito = () => {
			nav('/');
	}
	
	useEffect(() => {
		getDetails();
	}, []);


	return (
		<div style={{overflow: 'hidden', backgroundImage: "url(/ddd.jpeg)", height: '100vh', backgroundSize: 'cover'}}>{
			prize > -1 ?
			<Container>
				<Row className="m-2">
					<Col>
					<h2 className="text-center">
						Γύρισε τον τροχό και ένα δώρο σε περιμένει.
					</h2>	
					</Col>
				</Row>
				<Row className="justify-content-center mb-2">
					<Col xs='auto'>

									<Wheel 
							mustStartSpinning={start}
							prizeNumber={prize}
							startingOptionIndex={0}
							data={[
								{ option: language.prizes[0] },
								{ option: language.prizes[1] },
								{ option: language.prizes[2] },
								{ option: language.prizes[3] },
								{ option: language.prizes[4] },
								{ option: language.prizes[5] },
							]}
							backgroundColors={['#482a81', '#f5c903ff']}
							textColors={['#FFFFFF']}

							outerBorderColor={'#000000'}
							outerBorderWidth={5}
							radiusLineColor={'#000000'}
							radiusLineWidth={5}


							innerRadius={20}
							innerBorderColor={'#000000'}
							innerBorderWidth={5}

							fontSize={16}
							spinDuration={0.4}
							disableInitialAnimation={true}

							onStopSpinning={stopSpin}

						/>

					</Col>
				</Row>

				<Row className="justify-content-center">
					<Col xs='auto'>
					{
						show 
						? <Alert show={show} variant="warning" className="text-center">
							Συγχαρητηρια...!!!
							<hr/>
							{messages[prize]}
							<hr />
							<div className="d-flex justify-content-center">
							<Button onClick={finito} variant="outline-warning">
								ΟΚ
							</Button>
							</div>
						</Alert>
						:<Button onClick={startSpin} variant="warning" className="mt-5">
							Γύρισε τον Τροχό
						</Button>
					}
					</Col>
				</Row>
			
			
			
			</Container>
			:null
			}
		</div>
	);
};

export default MyWheel;