import './App.css';
import { Routes, Route, Outlet } from "react-router-dom";

import ProtectedRoute from "./components/ProtectedRoute";
import Index from "./pages/Index";
import VotingPage from "./pages/VotingPage";
import Results from "./pages/Results";
import MainLogin from "./pages/MainLogin";
import { Button, Col, Image, Row } from "react-bootstrap";
import Menu from "./components/Menu";
import { logOut } from "./context/AuthContext";
import CountriesManage from './pages/CountriesManage';
import MyWheel from './components/Wheel';
import Help from './components/Help';
import { BoxArrowRight } from 'react-bootstrap-icons';

const Layout = () => {
	return(
		<div style={{overflowY:'hidden'}}>
			<Image src="main_logo.png" rounded fluid />
			<Row className="justify-content-between p-0 mb-3">
				<Col xs='auto'>
					<Help/>
				</Col>
				<Col xs='auto'>
					<Button size="sm" variant="outline-dark" onClick={logOut}>Αποσύνδεση</Button>
				</Col>
			</Row>
			<Menu/>
			<Outlet />
			<div className='padd' />
		</div>
	);
}


export default function App() {
	return (
		<Routes>
			<Route path="/login" element={<MainLogin/>} />
			<Route path="/prize" element={<MyWheel/>}/>
			<Route path="/admin" element={<CountriesManage/>}/>
			<Route element={
				<ProtectedRoute> 
					<Layout/> 
				</ProtectedRoute>}>
					<Route path="/" element={ <Index/> }/>
					<Route path="/vote" element={ <VotingPage/> }/>
					<Route path="/results" element={ <Results/> }/>
			</Route>
		</Routes>
	);
}